<template>
<section ref="dialog" class="weather-popup" :class="kind" :style="positionStyle" role="dialog" aria-modal="false" tabindex="-1" :aria-label="kind==='alert'?'天气预警详情':'位置天气详情'" @click.stop>
 <header :style="kind==='alert'?{'--warning':alertColor}:{}"><strong>{{ title }}</strong><button type="button" aria-label="关闭天气浮窗" @click="emit('close')">×</button></header>
 <div class="popup-body">
  <template v-if="kind==='alert'&&alert"><dl class="alert-fields"><div><dt>发布时间</dt><dd>{{formatBeijing(alert.issuedTime)}}</dd></div><div v-if="alert.urgency"><dt>紧迫程度</dt><dd>{{weatherEnumZh(alert.urgency)}}</dd></div><div><dt>严重程度</dt><dd>{{weatherEnumZh(alert.severity)}}</dd></div><div v-if="alert.certainty"><dt>确定性</dt><dd>{{weatherEnumZh(alert.certainty)}}</dd></div></dl><section><h3>预警说明</h3><p>{{alert.description||'--'}}</p></section><section v-if="alert.criteria"><h3>触发标准</h3><p>{{alert.criteria}}</p></section><section v-if="alert.instruction"><h3>防御指南</h3><p>{{alert.instruction}}</p></section></template>
  <template v-else-if="bundle"><div class="query-context"><strong>{{queryObject}}</strong><span>{{pointNature}} · {{bundle.location.lat.toFixed(2)}}°N, {{bundle.location.lon.toFixed(2)}}°E</span></div><section class="current"><h3>当前天气</h3><div v-if="bundle.current.status==='success'" class="current-main"><QWeatherIcon :code="bundle.current.data.condition.code"/><strong>{{bundle.current.data.condition.text||'--'}} {{unitText(bundle.current.data.temperature)}}</strong></div><div v-else-if="bundle.current.status==='error'" class="module-error">实时天气加载失败 <button @click="emit('retry','current')">重试</button></div><div v-else-if="bundle.current.stale&&bundle.current.refreshError" class="module-error">实时天气更新失败，显示上次成功数据 <button @click="emit('retry','current')">重试</button></div><dl v-if="bundle.current.status==='success'"><div><dt>体感温度</dt><dd>{{unitText(bundle.current.data.feelsLike)}}</dd></div><div><dt>近一小时降水</dt><dd>{{unitText(bundle.current.data.precipitation?.amount)}}</dd></div><div><dt>降水强度</dt><dd>{{unitText(bundle.current.data.precipitation?.intensity)}}</dd></div><div><dt>降水类型</dt><dd>{{precipitationType(bundle.current.data.precipitation?.type)}}</dd></div><div><dt>湿度</dt><dd>{{percentage(bundle.current.data.humidity)}}</dd></div></dl><small v-if="bundle.current.status!=='error'">本站获取 {{formatBeijing(bundle.current.fetchedAt)}}</small></section>
   <section class="minutely"><h3>未来两小时降水 <small>每 5 分钟</small></h3><div v-if="minutelyKind==='error'" class="module-error">未来两小时降水加载失败 <button @click="emit('retry','minutely')">重试</button></div><p v-else-if="minutelyKind==='empty'">当前查询位置暂无分钟级降水预报</p><template v-else-if="minutelyData"><p>{{minutelyData.summary||'暂无降水摘要'}}</p><small>更新于 {{formatBeijing(minutelyData.updateTime,false)}}</small><div class="rain-legend"><span v-for="type in precipTypes" :key="type">{{precipitationType(type)}}</span></div><div class="bars" role="list" :aria-label="minuteA11y"><button v-for="item in minutelyData.minutely" :key="item.fxTime" type="button" role="listitem" :aria-label="`${formatBeijing(item.fxTime,false)}，5分钟累计${item.precip}毫米，${precipitationType(item.type)}`" :title="`${formatBeijing(item.fxTime,false)} ${item.precip} mm ${precipitationType(item.type)}`"><i :class="item.type||'other'" :style="{height:`${barHeight(item.precip)}%`}"></i></button></div><div class="minute-axis"><time v-for="index in minuteTicks" :key="index">{{formatBeijing(minutelyData.minutely[index]?.fxTime,false)}}</time></div><p v-if="minutelyKind==='zero'" class="zero">未来两小时暂无降水</p></template></section>
   <section class="hourly"><h3>未来 24 小时预报 <small>每小时</small><em v-if="hourly.incomplete">数据不完整：共 {{hourly.items.length}} 个时点</em></h3><div v-if="bundle.hourly.status==='error'||!hourly.items.length" class="module-error">未来 24 小时预报加载失败 <button @click="emit('retry','hourly')">重试</button></div><div v-else class="hour-shell"><span v-show="hourCanLeft" class="hour-hint left" aria-hidden="true">‹</span><div ref="hours" class="hour-strip" tabindex="0" aria-label="未来24小时天气，可使用左右方向键浏览" @scroll="updateHourHints" @keydown.left.prevent="scrollHours(-1)" @keydown.right.prevent="scrollHours(1)" @wheel="onHourWheel"><article v-for="(item,index) in hourly.items" :key="`${item.forecastTime}-${index}`"><time>{{hourTimeLabel(item.forecastTime,hourly.items[0]?.forecastTime||item.forecastTime,index)}}</time><QWeatherIcon :code="item.condition.code"/><strong>{{item.condition.text||'--'}}</strong><b>{{unitText(item.temperature)}}</b><span>降水 {{percentage(item.precipitation?.probability)}}</span><span>{{unitText(item.precipitation?.amount)}}</span></article></div><span v-show="hourCanRight" class="hour-hint right" aria-hidden="true">›</span></div></section>
   <p class="responsibility">天气数据约为 1 公里分辨率的查询点附近信息，仅供风险辅助判断，不代表整块地块或整个行政区域的实测结果，不作为定损或理赔依据。</p><div class="refer"><span v-for="a in bundle.attributions" :key="`${a.name}-${a.url}`">{{a.name}}</span><span v-for="s in minutelyData?.refer.sources||[]" :key="s">{{s}}</span><span v-for="l in minutelyData?.refer.license||[]" :key="l">{{l}}</span></div>
  </template><div v-else class="popup-loading" role="status"><i class="qi-999" aria-hidden="true"></i><strong>正在加载新位置天气…</strong><button type="button" @click="emit('retry','current')">重试</button></div>
 </div>
</section>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref} from 'vue';import type {WeatherAlert,WeatherBundle} from '../../features/weather/weatherTypes';import {formatBeijing,hourlyCards,hourTimeLabel,minutelyState,percentage,precipitationType,unitText,warningColor,weatherEnumZh} from '../../features/weather/weatherAdapter';import QWeatherIcon from './QWeatherIcon.vue'
const props=defineProps<{kind:'alert'|'location';title:string;bundle?:WeatherBundle|null;alert?:WeatherAlert|null;x:number;y:number;contextName?:string;parcelId?:string}>();const emit=defineEmits<{close:[];retry:[module:'current'|'minutely'|'hourly']}>();const dialog=ref<HTMLElement|null>(null),hours=ref<HTMLElement|null>(null),hourCanLeft=ref(false),hourCanRight=ref(false);const previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;onMounted(()=>nextTick(()=>{dialog.value?.focus();updateHourHints()}));onBeforeUnmount(()=>previousFocus?.focus());const positionStyle=computed(()=>({left:`clamp(192px, ${props.x}px, calc(100% - 192px))`,top:`clamp(110px, ${props.y}px, calc(100% - 18px))`}));const alertColor=computed(()=>props.alert?warningColor(props.alert):'#64748b');const minutelyKind=computed(()=>props.bundle?minutelyState(props.bundle.minutely):'empty');const minutelyData=computed(()=>props.bundle&&props.bundle.minutely.status!=='error'?props.bundle.minutely.data:null);const hourly=computed(()=>props.bundle?hourlyCards(props.bundle.hourly):{items:[],incomplete:false});const precipTypes=computed(()=>[...new Set(minutelyData.value?.minutely.map(i=>i.type||'other')||[])]);const minuteTicks=computed(()=>{const n=minutelyData.value?.minutely.length||0;if(!n)return[];return[...new Set([0,Math.round((n-1)*.25),Math.round((n-1)*.5),Math.round((n-1)*.75),n-1])]});const minuteA11y=computed(()=>`未来两小时实际返回 ${minutelyData.value?.minutely.length||0} 个时点`);const maxPrecip=computed(()=>Math.max(0,...(minutelyData.value?.minutely.map(i=>i.precip)||[])));const queryObject=computed(()=>props.bundle?.target==='picked'?'地图点选位置':props.bundle?.target==='parcel'?`${props.contextName||'当前村'}${props.parcelId?` · 地块 ${props.parcelId}`:''}`:props.contextName||'当前行政区域');const pointNature=computed(()=>props.bundle?.target==='picked'?'临时点附近':props.bundle?.target==='parcel'?'地块内部代表点附近':'行政区域代表点附近');function barHeight(v:number){return v===0?0:Math.max(8,v/(maxPrecip.value||1)*100)}function updateHourHints(){const el=hours.value;if(!el)return;hourCanLeft.value=el.scrollLeft>1;hourCanRight.value=el.scrollLeft+el.clientWidth<el.scrollWidth-1}function scrollHours(dir:number){hours.value?.scrollBy({left:dir*180,behavior:'smooth'});requestAnimationFrame(updateHourHints)}function onHourWheel(e:WheelEvent){if(!hours.value||Math.abs(e.deltaY)<=Math.abs(e.deltaX))return;const can=e.deltaY>0?hours.value.scrollLeft+hours.value.clientWidth<hours.value.scrollWidth:hours.value.scrollLeft>0;if(can){e.preventDefault();hours.value.scrollLeft+=e.deltaY;updateHourHints()}}
</script>
